<?php
/**
 * DEV-only UE2 actual reader versus independent Epic source-wire fields on
 * authentic historical Core.u and Engine.u files archived from actual game
 * patch binaries. Independent evidence generated by the existing Python
 * source-derived decoder. No production originals/DB/UEDB5 mutated.
 */
declare(strict_types=1);
require_once dirname(__DIR__,2).'/catalog/lib/CatalogSupport.php';

use UnrealDb\Catalog\Infrastructure\Readers\CatalogUE2PackageReader;

$options=getopt('', ['archive-root::','evidence::','help']);
if (isset($options['help'])) {echo "Usage: php tests/tools/verify_ue2_native_update_packages_reader.php [--archive-root=D:\\Temp\\UnrealDB\\UE2\\native-version-archive] [--evidence=...]\n";exit(0);}
$root=(string)($options['archive-root']??'D:/Temp/UnrealDB/UE2/native-version-archive');
$evidence=(string)($options['evidence']??dirname(__DIR__).'/evidence/ue2/ue2-authentic-native-build-script-packages-20261106.json');
$proof=json_decode((string)file_get_contents($evidence),true,512,JSON_THROW_ON_ERROR);
if(($proof['read_only']??false)!==true || count((array)($proof['cases']??[]))!==30)throw new RuntimeException('Independent 30-package source evidence unavailable');
$hashRows=static fn(array $rows):string=>hash('sha256',json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));
$errors=[];$checks=0;$totals=['names'=>0,'imports'=>0,'exports'=>0];
$perGame=[];$mismatchExamples=[];
foreach($proof['cases'] as $case) {
    $relative=(string)$case['archive_relative_path'];
    if(str_contains($relative,'..') || str_starts_with($relative,'/'))throw new RuntimeException('Unsafe archive-relative path');
    $path=rtrim($root,'/\\').DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$relative);
    if(!is_file($path)){$errors[]="missing: $relative";continue;}
    $hash=hash_file('sha256',$path);
    if(!hash_equals($case['sha256'],$hash)){$errors[]="archive SHA mismatch: $relative";continue;}
    try {
        $reader=new CatalogUE2PackageReader($path);
        $problems=$reader->validatePackage();
        if($problems!==[])throw new RuntimeException("reader invalid: ".implode(' | ',$problems));
        $header=$reader->getHeader();
        if((int)($header['version']??-1)!==(int)$case['version']||(int)($header['licenseeVersion']??-1)!==(int)$case['licensee'])
            throw new RuntimeException("source version mismatch");
        $names=[];
        foreach($reader->getNames() as $r){$names[]=[(int)$r['offset'],(string)$r['name'],(int)$r['flags']];}
        $imports=[];
        foreach($reader->getImports() as $r){$imports[]=[(int)$r['offset'],(int)$r['classPackage'],
            (int)$r['className'],(int)$r['outerIndex'],(int)$r['objectName']];}
        $exports=[];
        foreach($reader->getExports() as $r){$exports[]=[(int)$r['offset'],(int)$r['classIndex'],(int)$r['superIndex'],
            (int)$r['outerIndex'],(int)$r['objectName'],(int)$r['objectFlags'],(int)$r['serialSize'],(int)$r['serialOffset']];}
        foreach(['name'=>$names,'import'=>$imports,'export'=>$exports] as $kind=>$rows){
            $expected=(int)$case[$kind.'_count'];
            if(count($rows)!==$expected)throw new RuntimeException("$kind count ".count($rows)." != ".$expected);
            $digest=$hashRows($rows);
            if(!hash_equals($case['full_'.$kind.'_fields_sha256'],$digest))
                throw new RuntimeException("$kind full fields mismatch source ".$case['full_'.$kind.'_fields_sha256']." reader ".$digest);
            $totals[match($kind){'name'=>'names','import'=>'imports','export'=>'exports'}]+=count($rows);
        }
        unset($names,$imports,$exports,$reader);
        $checks++;
        $key=(string)$case['game'];
        $perGame[$key]=($perGame[$key]??0)+1;
        echo "PASS_NATIVE_SCRIPT_PACKAGE ".$case['game']." ".$case['build']."/".$case['script_package']." version=".$case['version']."/".$case['licensee']." all_fields=match\n";
    }catch(Throwable $e){$errors[]="$relative: ".$e->getMessage();}
}
$expect=$proof['summary'];
foreach(['names'=>'name_rows','imports'=>'import_rows','exports'=>'export_rows'] as $key=>$reference){
    if($totals[$key] !== (int)$expect[$reference])$errors[]="$key total row count mismatch";
}
if($checks!==30)$errors[]="expected 30 successful packages, observed $checks";
$ok=$errors===[];
echo json_encode(['ok'=>$ok,'mode'=>'DEV_READ_ONLY','original_game_binaries_executed'=>false,
    'native_builds'=>15,'script_packages'=>$checks,'games'=>$perGame,
    'exact_per_entry_field_and_offset_rows'=>$totals,'errors'=>$errors],
    JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),PHP_EOL;
exit($ok?0:2);
